# nodescript.jl — the Plot with GMT.jl script as a graph of boxes (deps/src/71_nodegraph.cpp).
# Unit tier: the parser and the one-statement rewrite, on script text. GUI tier: the editor's real
# Graph… button, and a field edited by a real click in the graph and typing in place.

@testitem "nodescript: a generated script parses into boxes, wires and the paint chain" tags=[:unit, :fast, :gmtscript] begin
	M = InteractiveGMT
	src = """
	# Generated by InteractiveGMT — reproduction of an iGMT window as GMT.jl calls.

	using GMT

	const REG     = (-10, 10, 30, 50)
	const PROJ    = :merc
	const FIGSIZE = 15

	# ── grid 'topo.nc'
	G1 = gmtread("topo.nc")
	C1 = makecpt(cmap=:geo, range=(-5000, 3000))
	grdimage(G1, cmap=C1, region=REG, proj=PROJ, figsize=FIGSIZE)

	# ── overlay 'coast'
	# X1: exists only in the viewer, never on disk — fetched from the live window
	X1 = InteractiveGMT._xy_series_data(Ptr{Nothing}(UInt(0x0123)), 1, 2)
	pen1 = "1p,red"    # pen: width,colour[,style] — edit here
	plot!(X1, pen=pen1)   # a note of mine

	colorbar!(C1, pos=(anchor=:MR, offset=(1, 0)))

	showfig()
	"""
	nodes, wires, links = M._nodegraph_parse(src)
	kinds = [n.kind for n in nodes]
	@test kinds == [:figure, :data, :palette, :call, :data, :call, :call, :output]
	title(id) = nodes[id].title
	@test [f.label for f in nodes[1].fields] == ["REG", "PROJ", "FIGSIZE"]
	# the step heading is the CALL's note; a value's own comment is the value's
	# boxes are titled in words first, the GMT.jl name after
	@test nodes[4].note == "grid 'topo.nc'" && title(4) == "Grid as image  (grdimage)"
	@test title(2) == "G1 · Read file" && title(3) == "C1 · Colour palette" && title(5) == "X1 · from the window"
	@test occursin("exists only in the viewer", nodes[5].note)
	# the pen is a field of the call that uses it, pointing at the pen's OWN line, edited as a LINE
	pf = only(f for f in nodes[6].fields if f.label == "pen")
	@test pf.value == "\"1p,red\"" && pf.key == "=" && pf.type == "pen" && pf.plain == "Line"
	@test pf.shown == "1 pt, red, solid"
	@test !any(n -> startswith(n.title, "pen"), nodes)
	# every common value has a dialog in plain words, not GMT.jl syntax
	fld(id, lab) = only(f for f in nodes[id].fields if f.label == lab)
	@test fld(1, "REG").type == "nums" && fld(1, "REG").shown == "West -10, East 10, South 30, North 50"
	@test fld(1, "PROJ").type == "choice" && fld(1, "PROJ").shown == "Mercator" &&
	      occursin("Equidistant conic", fld(1, "PROJ").extra)          # offered centred on THIS region
	@test fld(1, "FIGSIZE").type == "number" && fld(1, "FIGSIZE").plain == "Map width (cm)"
	@test fld(3, "cmap").type == "choice" && fld(3, "cmap").shown == "geo" && fld(3, "cmap").plain == "Colour palette"
	@test fld(3, "range").type == "nums" && fld(3, "range").shown == "From -5000, To 3000"
	@test fld(2, "arg1").type == "file" && fld(2, "arg1").shown == "topo.nc"
	@test fld(4, "data").type == "ref" && fld(4, "data").stmt == 0                 # made by another box
	@test fld(7, "pos").type == "choice" && fld(7, "pos").shown == "Right of the map"
	@test only(nodes[5].fields).type == "none"                     # the window fetch: nothing to touch
	# wires: G1 -> grdimage.data, C1 -> grdimage.cmap and colorbar!.data, X1 -> plot!.data; none from REG
	@test Set((title(a), title(b), l) for (a, b, l) in wires) ==
	      Set([(title(2), title(4), "data"), (title(3), title(4), "cmap"), (title(3), title(7), "data"),
	           (title(5), title(6), "data")])
	@test [(a, b) for (a, b) in links] == [(1, 4), (4, 6), (6, 7), (7, 8)]
	# values sit one column left of their user, at its height
	@test nodes[2].col == 1 && nodes[2].anchor == 4 && nodes[5].anchor == 6
	# the blob: one record per line, nothing with a tab or newline inside a value
	blob = M._nodegraph_blob(nodes, wires, links)
	@test count(startswith("N\t"), split(blob, '\n')) == length(nodes)
	@test all(l -> isempty(l) || l[1] in "NFWL", split(blob, '\n'))
end

@testitem "nodescript: an edit rewrites ONE statement, nothing else" tags=[:unit, :fast, :gmtscript] begin
	M = InteractiveGMT
	src = "using GMT\n\nconst REG = (0, 1, 0, 1)\n# ── grid\nC1 = makecpt(cmap=:geo, range=(0, 1))\n" *
	      "pen1 = \"1p,red\"    # pen here\ngrdimage(G1, cmap=C1, frame=(annot=:auto, axes=:WSen))  # mine\nshowfig()\n"
	diff(a, b) = [(x, y) for (x, y) in zip(split(a, '\n'), split(b, '\n')) if x != y]
	# a kwarg
	out = M._nodegraph_rewrite(src, 3, "cmap", ":jet")
	@test diff(src, out) == [("C1 = makecpt(cmap=:geo, range=(0, 1))", "C1 = makecpt(cmap=:jet, range=(0, 1))")]
	# a pen: its own line, the trailing comment kept
	out = M._nodegraph_rewrite(src, 4, "=", "\"2p,blue\"")
	@test only(diff(src, out))[2] == "pen1 = \"2p,blue\"    # pen here"
	# a positional argument of a call that carries a trailing comment
	out = M._nodegraph_rewrite(src, 5, "#1", "G2")
	@test only(diff(src, out))[2] == "grdimage(G2, cmap=C1, frame=(annot=:auto, axes=:WSen))  # mine"
	# a const
	@test only(diff(src, M._nodegraph_rewrite(src, 2, "=", "(-1, 1, -1, 1)")))[2] == "const REG = (-1, 1, -1, 1)"
	# what cannot be done says so, and changes nothing
	@test_throws ErrorException M._nodegraph_rewrite(src, 3, "nosuch", "1")
	@test_throws ErrorException M._nodegraph_rewrite(src, 3, "cmap", "(1, ")
	@test_throws ErrorException M._nodegraph_rewrite(src, 99, "cmap", ":jet")
	# the frame is offered as its parts, in words
	fr = only(f for n in M._nodegraph_parse(src)[1] for f in n.fields if f.label == "frame")
	@test fr.type == "frame" && fr.shown == "numbers" && occursin("WSen", fr.extra)
	# a colour bar's frame: its two labels are offered (and it is flagged as a bar's, for its own form)
	cb = "colorbar!(C1, pos=(anchor=:MR, offset=(1, 0)), frame=(annot=:auto, xlabel=\"Elevation\", ylabel=\"m\"))\n"
	fb = only(f for n in M._nodegraph_parse(cb)[1] for f in n.fields if f.label == "frame")
	@test fb.type == "frame" && fb.shown == "numbers, X label \"Elevation\", Y label \"m\""
	@test occursin("xlabel\x1fElevation", fb.extra) && occursin("ylabel\x1fm", fb.extra) && occursin("bar\x1f1", fb.extra)
	@test occursin("bar\x1f0", fr.extra)                       # a map frame is not a bar's
	# what the form writes back for new labels lands in the call
	@test occursin("frame=(annot=:auto, xlabel=\"Depth\", ylabel=\"km\")",
	               M._nodegraph_rewrite(cb, 1, "frame", "(annot=:auto, xlabel=\"Depth\", ylabel=\"km\")"))
	# a Yes/No flag switched off is written `nothing` (GMT.jl asserts on `false`), stays a Yes/No field,
	# runs, and switches back on
	s1 = "C = makecpt(cmap=:turbo, range=(-6183.9604, 2245.5295), continuous=true)\n"
	off = M._nodegraph_rewrite(s1, 1, "continuous", "false")
	@test occursin("continuous=nothing", off)
	fl = only(f for n in M._nodegraph_parse(off)[1] for f in n.fields if f.label == "continuous")
	@test fl.type == "bool" && fl.shown == "No" && fl.extra == "0"
	@test M.GMT.makecpt(cmap=:turbo, range=(-6183.9604, 2245.5295), continuous=nothing) isa M.GMT.GMTcpt
	@test M._nodegraph_rewrite(off, 1, "continuous", "true") == s1
	# a hand-written script: anything that is not a call or an assignment is a plain Julia box
	nodes, _, _ = M._nodegraph_parse("using GMT\nfor i in 1:3\n  println(i)\nend\nplot(rand(5))\n")
	@test [n.kind for n in nodes] == [:julia, :call]
end

@testitem "nodescript: a step is added and removed through the text" tags=[:unit, :fast, :gmtscript] begin
	M = InteractiveGMT
	src = "using GMT\n\nconst REG = (-10, 0, 35, 45)\nconst PROJ = :merc\nconst FIGSIZE = 12\n\n" *
	      "# ── grid 'topo.nc'\nG1 = gmtread(\"topo.nc\")\nC1 = makecpt(cmap=:geo, range=(-5000, 3000))\n" *
	      "grdimage(G1, cmap=C1, region=REG, proj=PROJ, figsize=FIGSIZE)\n\ncolorbar!(C1, pos=(anchor=:MR, offset=(1, 0)))\n\nshowfig()\n"
	lines(s) = split(s, '\n')
	added(a, b) = [l for l in lines(b) if !(l in lines(a))]
	# after a call, from a grid box: a `!` call under its own heading, every old line still there
	out = M._nodegraph_insert(src, 7, "after", "grdcontour", "G1", "")
	@test added(src, out) == ["# ── Contours", "grdcontour!(G1, pen=\"0.5p,black\")"]
	@test all(l -> l in lines(out), lines(src))
	@test findfirst(==("grdcontour!(G1, pen=\"0.5p,black\")"), lines(out)) <
	      findfirst(startswith("colorbar!"), lines(out))
	nodes, _, links = M._nodegraph_parse(out)
	@test count(n -> n.kind === :call, nodes) == 3 && length(links) == 4
	# at the end: before showfig; text at the centre of the map limits; nothing needed to draw from
	out = M._nodegraph_insert(src, 0, "end", "text")
	@test lines(out)[end-1] == "showfig()" && occursin("text!(text=\"Label\", x=-5, y=40, font=14)", out)
	# from a file: a new data box read first, then the call drawing from it
	out = M._nodegraph_insert(src, 8, "before", "plot", "", "C:/data/track.txt")
	@test added(src, out) == ["# ── Lines", "D1 = gmtread(\"C:/data/track.txt\")", "plot!(D1, pen=\"1p,black\")"]
	# before the first call (never in front of the set-up): it opens the figure, the old opener gets its `!`
	out = M._nodegraph_insert(src, 2, "after", "coast")
	@test occursin("coast(shore=\"0.5p,black\", region=REG, proj=PROJ, figsize=FIGSIZE)", out)
	@test occursin("grdimage!(G1, cmap=C1, region=REG", out)
	@test findfirst(startswith("coast("), lines(out)) > findfirst(startswith("const FIGSIZE"), lines(out))
	# a grid as a 3-D surface: drawn from the grid box, with its own viewpoint
	out = M._nodegraph_insert(src, 7, "after", "grdview", "G1", "")
	@test added(src, out) == ["# ── Grid as 3-D surface", "grdview!(G1, cmap=:turbo, surftype=:image, view=(200, 30))"]
	@test_throws ErrorException M._nodegraph_insert(src, 7, "after", "grdcontour")    # nothing to draw from
	@test_throws ErrorException M._nodegraph_insert(src, 7, "after", "nosuch", "G1")
	# removal undoes the add, byte for byte
	out = M._nodegraph_insert(src, 7, "after", "grdcontour", "G1", "")
	@test M._nodegraph_delete(out, 8) == src
	out = M._nodegraph_insert(src, 8, "before", "plot", "", "C:/data/track.txt")
	@test M._nodegraph_delete(out, 9) == src                         # its data box goes with it
	# the opener removed: its grid goes (only it read it), the palette stays (the colour bar reads it), and
	# the next call opens the figure with the frame the old one set
	out = M._nodegraph_delete(src, 7)
	@test !occursin("gmtread", out) && !occursin("grid 'topo.nc'", out) && occursin("C1 = makecpt", out)
	@test occursin("colorbar(C1, pos=(anchor=:MR, offset=(1, 0)), region=REG, proj=PROJ, figsize=FIGSIZE)", out)
	@test_throws ErrorException M._nodegraph_delete(src, 6)          # a palette still in use
	@test_throws ErrorException M._nodegraph_delete(src, 2)          # the Figure box
	# the menu: every module, and the data boxes with what they hold (not run: offered to every module)
	nodes, _, _ = M._nodegraph_parse(src)
	mb = M._nodegraph_menu_blob(src, nodes, nothing)
	@test count(startswith("M\t"), lines(mb)) == length(M._NG_MODULES)
	@test only(filter(startswith("V\t"), lines(mb))) == "V\tG1\t?\tG1 · Read file"
end

@testitem "nodescript: an edit redraws only what it reaches, same pictures as a full run" tags=[:unit, :gmtscript] begin
	M = InteractiveGMT; GMT = M.GMT
	G = GMT.grdmath("-R-10/-5/35/40 -I0.02 X Y MUL")
	I = GMT.mat2img(rand(UInt8, 200, 300, 3), x=[-10., -5], y=[35., 40], proj4="+proj=longlat +datum=WGS84 +no_defs")
	Core.eval(Main, :(_ng_test_G = $G; _ng_test_I = $I))
	src = "using GMT\nconst REG = (-10, -5, 35, 40)\nG1 = Main._ng_test_G\nI1 = Main._ng_test_I\n" *
	      "C1 = makecpt(cmap=:turbo, range=(-500, 0), continuous=true)\n" *
	      "grdview(G1, drape=I1, surftype=:image, region=REG, proj=\"M\", figsize=10, view=(200, 30), frame=(annot=:auto, axes=:WSen))\n" *
	      "colorbar!(cmap=C1, pos=(anchor=:MR, offset=(1.0, 0.0)), frame=(annot=:auto,))\n" *
	      "GMT.plot!([-9 36; -6 39], pen=\"1p,red\")\nshowfig()\n"
	h = Ptr{Cvoid}(7)
	for (stmt, key, val, replays) in ((5, "continuous", "false", true),   # the drape ignores the palette
	                                  (6, "view", "(150, 40)", false))     # the first call itself
		nodes, _, _ = M._nodegraph_parse(src)
		M._nodegraph_previews(src, nodes, h, true)
		s2 = M._nodegraph_rewrite(src, stmt, key, val)
		n2, _, _ = M._nodegraph_parse(s2)
		before = M._NG_RUNS[h]
		p, e = M._nodegraph_previews(s2, n2, h, false)
		@test isempty(e)
		@test (M._NG_RUNS[h].ps[6] === before.ps[6]) == replays    # the drape kept as drawn, or redrawn
		pf, ef = M._nodegraph_previews(s2, n2, h, true)
		@test isempty(ef) && keys(p) == keys(pf) && all(p[k] == pf[k] for k in keys(p))
	end
	# a call with no palette of its own after the edited palette is redrawn, never replayed
	nodes, _, _ = M._nodegraph_parse(src)
	M._nodegraph_previews(src, nodes, h, true)
	s3 = M._nodegraph_rewrite(src, 5, "cmap", ":jet")
	@test M._ng_reads_cpt(M._ng_statements(s3)[8].ex, Main)
	@test !M._ng_reads_cpt(M._ng_statements(s3)[6].ex, M._NG_RUNS[h].mod)
	delete!(M._NG_RUNS, h)
end

@testitem "nodescript: the editor's Graph… button opens the graph, a clicked field edits the script in place" tags=[:gui] setup=[GmtvtkTest] begin
	IG = InteractiveGMT; GMT = IG.GMT
	btn(title, name) = ccall(GmtvtkTest._test_fn(:gmtvtk_dialog_button_test), Cint,
	                         (Cstring, Cstring, Cint, Ptr{UInt8}, Cint), title, name, 1, C_NULL, 0)
	graph(label, text) = ccall(GmtvtkTest._test_fn(:gmtvtk_nodegraph_test), Cint, (Cstring, Cstring), label, text)
	active(name) = ccall(GmtvtkTest._test_fn(:gmtvtk_window_active_test), Cint, (Cstring,), name)
	G = GMT.mat2grid(Float32[sin(ix / 3) * cos(iy / 4) for iy in 0:29, ix in 0:29]; x=[0.0, 29.0], y=[0.0, 29.0])
	f = InteractiveGMT.viz(G)
	try
		IG._script_open_editor(f.h)
		IG._pump_once()
		# the editor reports what the script cannot reproduce (a lit surface is captured as an image)
		@test all(e -> startswith(e, "script: "), IG._take_tool_errors!())
		@test graph("", "") == 0                                     # no graph before the click
		@test btn("Plot with GMT.jl", "scriptGraphBtn") == 1
		for _ in 1:20; IG._pump_once(); end
		src = IG._script_editor_text(f.h)
		nodes, _, _ = IG._nodegraph_parse(src)
		@test graph("", "") == length(nodes)                         # one box per parsed statement
		@test active("nodeGraphWindow") == 1                         # on screen AND in front
		# change the palette by clicking its row and picking "jet" from the list: one line of the text changes
		@test graph("cmap", "jet") == 1
		for _ in 1:20; IG._pump_once(); end
		out = IG._script_editor_text(f.h)
		changed = [(a, b) for (a, b) in zip(split(src, '\n'), split(out, '\n')) if a != b]
		@test length(changed) == 1 && occursin("cmap=:jet", changed[1][2])
		@test graph("", "") == length(nodes)                         # the graph was rebuilt from the new text
		# steps added and removed by the user's own gestures: each one changes the script text, and the graph
		# is rebuilt from it
		step(how, target, path) = ccall(GmtvtkTest._test_fn(:gmtvtk_nodegraph_step_test), Cint,
		                                (Cstring, Cstring, Cstring), how, target, path)
		pump() = for _ in 1:30; IG._pump_once(); end
		lines() = split(IG._script_editor_text(f.h), '\n')
		at(pre) = findfirst(startswith(pre), lines())
		boxes_ok() = graph("", "") == length(IG._nodegraph_parse(IG._script_editor_text(f.h))[1])
		# the Add step button: at the end, just before the figure is shown
		@test step("button", "", "Annotations/Text label") == 1
		pump()
		@test at("text!(text=\"Label\"") !== nothing && at("text!(") < at("showfig(") && boxes_ok()
		# a module dragged from the palette onto the link leaving the text step: right after it
		@test step("drop", "Text labels", "gridlines") == 1
		pump()
		@test at("basemap!(frame=(grid=:auto,))") == at("text!(") + 3 && boxes_ok()   # a blank line and its heading between
		# a step's own menu: add after it
		@test step("box", "Map frame", "Add a step after/Annotations/Colour bar") == 1
		pump()
		@test at("colorbar!(pos=") !== nothing && at("colorbar!(pos=") > at("basemap!(frame=(grid") && boxes_ok()
		# and remove one: its line and heading go, nothing else
		before = lines()
		@test step("box", "Text labels", "Remove this step") == 1
		pump()
		gone = setdiff(before, lines())
		@test at("text!(") === nothing && length(gone) == 2 && gone[1] == "# ── Text label" &&
		      startswith(gone[2], "text!(text=\"Label\"") && boxes_ok()
	finally
		ccall(IG._fn(:gmtvtk_close), Cvoid, (Ptr{Cvoid},), f.h)
	end
end
